-- =============================================================================
-- 037: Solar Evals — clearer form names, one CE and one Integration PM form
-- =============================================================================
-- Run once, after 036: Supabase → SQL Editor → New query → paste → Run.
--
--   * The member-eval forms say who they're for: the main form is "Member eval",
--     and each division's variant is "<division> members" (was "<division> CE"),
--     since they're for evaluating a division's members, not its CE.
--   * Leadership eval: one "Chief Engineer" variant and one "Integration Project
--     Manager" variant for both divisions, instead of a Mechanical and an
--     Electrical one of each. Their role rows are worded for either division,
--     and a "Division" header field says which one. The four old variants are
--     taken off the Forms list (unless an eval type uses one); evals already
--     written on them keep their own copy.
-- =============================================================================

update public.eval_tracks set name = 'Member eval', updated_at = now()
where id = 'master' and name in ('Master template', 'Master', 'Master rubric');

update public.eval_tracks set name = regexp_replace(name, '\s+CE$', '', 'i') || ' members', updated_at = now()
where parent_id = 'master' and removed_at is null and name !~* 'members$' and length(regexp_replace(name, '\s+CE$', '', 'i')) <= 52;

-- One Chief Engineer form and one Integration Project Manager form, for both divisions.
insert into public.eval_tracks (id, name, kind, parent_id, color, sort) values
  ('lead-ce', 'Chief Engineer', 'ce', 'leadership', '#C2622A', 16),
  ('lead-pm', 'Integration Project Manager', 'ce', 'leadership', '#8A3F7A', 18)
on conflict (id) do nothing;
