update public.eval_tracks t set removed_at = now(), updated_at = now()
where t.id in ('lead-mech-ce', 'lead-elec-ce', 'lead-mech-pm', 'lead-elec-pm') and t.removed_at is null
  and not exists (select 1 from public.eval_types y where y.settings -> 'form' ->> 'track' = t.id);

update app_settings set value = jsonb_set(value, '{schemaVersion}', '37') where key = 'general';
